import{c as t,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const k=JSON.parse('{"title":"BlockReduceMax","description":"","frontmatter":{},"headers":[{"level":1,"title":"BlockReduceMax","slug":"blockreducemax"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/归约计算/BlockReduceMax.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/归约计算/BlockReduceMax.md"}'),l={name:"api/SIMD-API/基础API/Memory矢量计算/归约计算/BlockReduceMax.md"};function p(d,a,i,r,c,o){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="blockreducemax" tabindex="-1">BlockReduceMax <a class="header-anchor" href="#blockreducemax" aria-label="Permalink to &quot;BlockReduceMax&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>对每个datablock内所有元素求最大值。归约指令的总体介绍请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/guide/%E7%BC%96%E7%A8%8B%E6%8C%87%E5%8D%97/%E7%B1%BB%E5%BA%93API/%E5%9F%BA%E7%A1%80API/%E5%B8%B8%E7%94%A8%E6%93%8D%E4%BD%9C%E9%80%9F%E6%9F%A5%E6%8C%87%E5%AF%BC/%E5%A6%82%E4%BD%95%E4%BD%BF%E7%94%A8%E5%BD%92%E7%BA%A6%E8%AE%A1%E7%AE%97API.md" target="_blank" rel="noreferrer">如何使用归约计算API</a>。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void BlockReduceMax(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src,const int32_t repeatTime, const uint64_t mask[], const int32_t dstRepStride, const int32_t srcBlkStride, const int32_t srcRepStride)</span></span></code></pre></div></li><li><p>mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void BlockReduceMax(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src,const int32_t repeatTime, const int32_t mask, const int32_t dstRepStride, const int32_t srcBlkStride, const int32_t srcRepStride)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：half/float Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half/float Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half/float Atlas 200I/500 A2 推理产品，支持的数据类型为：half/float Atlas 推理系列产品AI Core，支持的数据类型为：half/float Atlas 训练系列产品，支持的数据类型为：half Kirin X90，支持的数据类型为：half/float Kirin 9030，支持的数据类型为：half/float</td></tr><tr><td>isSetMask</td><td>是否在接口内部设置mask。 true，表示在接口内部设置mask。false，表示在接口外部设置mask，开发者需要使用SetVectorMask接口设置mask值。这种模式下，接口入参中的mask值设置为占位符MASK_PLACEHOLDER，用于占位，无实际含义。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要保证16字节对齐（针对half数据类型），32字节对齐（针对float数据类型）。</td></tr><tr><td>src</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>repeatTime</td><td>输入</td><td>迭代次数。取值范围为[0, 255]。 关于该参数的具体描述请参考高维切分API。</td></tr><tr><td>mask/mask[]</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。 逐bit模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。 mask为数组形式，数组长度和数组元素的取值范围和操作数的数据类型有关。当操作数为16位时，数组长度为2，mask[0]、mask[1]∈[0, 264-1]并且不同时为0；当操作数为32位时，数组长度为1，mask[0]∈(0, 264-1]；当操作数为64位时，数组长度为1，mask[0]∈(0, 232-1]。 例如，mask=[8, 0]，8=0b1000，表示仅第4个元素参与计算。 连续模式：表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask∈[1, 128]；当操作数为32位时，mask∈[1, 64]；当操作数为64位时，mask∈[1, 32]。</td></tr><tr><td>dstRepStride</td><td>输入</td><td>目的操作数相邻迭代间的地址步长。以一个repeatTime归约后的长度为单位。 每个repeatTime(8个datablock)归约后，得到8个元素，所以输入类型为half类型时，RepStride单位为16Byte；输入类型为float类型时，RepStride单位为32Byte。 注意，此参数值Atlas 训练系列产品不支持配置0。</td></tr><tr><td>srcBlkStride</td><td>输入</td><td>单次迭代内datablock的地址步长。详细说明请参考dataBlockStride。</td></tr><tr><td>srcRepStride</td><td>输入</td><td>源操作数相邻迭代间的地址步长，即源操作数每次迭代跳过的datablock数目。详细说明请参考repeatStride。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>为了节省地址空间，您可以定义一个Tensor，供源操作数与目的操作数同时使用（即地址重叠），需要注意计算后的目的操作数数据不能覆盖未参与计算的源操作数，需要谨慎使用。</p></li><li><p>对于Atlas 200I/500 A2 推理产品，若配置mask/mask[]参数后，存在某个datablock里的任何一个元素都不参与计算，则该datablock内所有元素的最大值会填充为-inf返回。比如float场景下，当mask配置为32，即只计算前4个datablock，则后四个datablock内的最大值会返回-inf。half场景下会返回-65504。</p></li><li><p>针对不同场景合理使用归约指令可以带来性能提升，相关介绍请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/guide/%E7%AE%97%E5%AD%90%E5%AE%9E%E8%B7%B5%E5%8F%82%E8%80%83/SIMD%E7%AE%97%E5%AD%90%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96/%E7%9F%A2%E9%87%8F%E8%AE%A1%E7%AE%97/%E9%80%89%E6%8B%A9%E4%BD%8E%E5%BB%B6%E8%BF%9F%E6%8C%87%E4%BB%A4-%E4%BC%98%E5%8C%96%E5%BD%92%E7%BA%A6%E6%93%8D%E4%BD%9C%E6%80%A7%E8%83%BD.md" target="_blank" rel="noreferrer">选择低延迟指令，优化归约操作性能</a>，具体样例请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/03_libraries/04_reduce/reduce" target="_blank" rel="noreferrer">ReduceCustom</a>。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本样例中只展示Compute流程中的部分代码。完整样例可参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/02_memory_vector_compute/block_reduce_min_max_sum" target="_blank" rel="noreferrer">BlockReduce系列归约指令样例</a>。</p><ul><li><p>BlockReduceMax-tensor高维切分计算样例-mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 设定mask为最多的128个全部元素参与计算</span></span>
<span class="line"><span>int32_t mask = 256/sizeof(half);</span></span>
<span class="line"><span>// 每个repeat128个元素，一共128个元素。</span></span>
<span class="line"><span>int repeat = 1;</span></span>
<span class="line"><span>// dstLocal: 目的操作数tensor</span></span>
<span class="line"><span>// srcLocal: 源操作数tensor</span></span>
<span class="line"><span>// srcBlkStride = 1, 在一个repeat中，block间没有空隙。</span></span>
<span class="line"><span>// dstRepStride = 1, srcRepStride = 8, repeat间没有空隙。</span></span>
<span class="line"><span>AscendC::BlockReduceMax&lt;half&gt;(dstLocal, srcLocal, repeat, mask, 1, 1, 8);</span></span></code></pre></div></li><li><p>BlockReduceMax-tensor高维切分计算样例-mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 设定mask为最多的128个全部元素参与计算</span></span>
<span class="line"><span>uint64_t mask[2] = { UINT64_MAX, UINT64_MAX };</span></span>
<span class="line"><span>// 每个repeat128个元素，一共128个元素。</span></span>
<span class="line"><span>int repeat = 1;</span></span>
<span class="line"><span>// dstLocal: 目的操作数tensor</span></span>
<span class="line"><span>// srcLocal: 源操作数tensor</span></span>
<span class="line"><span>// srcBlkStride = 1, 在一个repeat中，block间没有空隙。</span></span>
<span class="line"><span>// dstRepStride = 1, srcRepStride = 8, repeat间没有空隙。</span></span>
<span class="line"><span>AscendC::BlockReduceMax&lt;half&gt;(dstLocal, srcLocal, repeat, mask, 1, 1, 8);</span></span></code></pre></div></li></ul><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据src_gm: </span></span>
<span class="line"><span>[1, 1, 1, 1, 1, 1, 1, 1,</span></span>
<span class="line"><span> 1, 1, 2, 1, 1, 1, 1, 1,</span></span>
<span class="line"><span> 1, 1, 1, 1, 1, 1, 1, 1,</span></span>
<span class="line"><span> 1, 1, 1, 1, 1, 3, 1, 1,</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> 1, 1, 1, 4, 1, 1, 1, 1,</span></span>
<span class="line"><span> 1, 1, 1, 1, 1, 1, 1, 1,</span></span>
<span class="line"><span>]  </span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出数据dst_gm: </span></span>
<span class="line"><span>[2, 3, ..., 4]</span></span></code></pre></div>`,21)])])}const m=t(l,[["render",p]]);export{k as __pageData,m as default};
